* Control Block
.control
  op
  let pwr = -i(VDD) * 1.8
  print pwr

  * AC simulation from 100 kHz to 1 GHz as in Baker text
  ac dec 100 100k 1G

  let gain_mag = abs(v(out))
  let gain_db = vdb(out)
  let beta_calc = 1000.0 / (1000.0 + 9000.0)
  print beta_calc

  meas ac acl_linear find gain_mag at=100k
  meas ac acl_db find gain_db at=100k
  meas ac f_3db when gain_db=(acl_db-3) fall=1

  quit
.endc

.end

